<template>
  <section class="private-office" :style="{'--office-accent':officeAccent(room?.branding)}" :class="{'office-active':video||externalMeeting,'auricwell-surface':auricwell}">
    <header class="office-header"><OfficeBrand :branding="room?.branding" /><span v-if="plan" class="plan-badge">{{ plan.name }}</span></header>
    <div class="office-heading"><div><p class="eyebrow">{{ auricwell ? 'Your space for care' : 'Your space to connect' }}</p><h1>My Virtual Office</h1><p>Welcome guests, connect, and make space for a conversation.</p></div><div class="office-state" :class="{ready:canAdmit}"><span></span>{{ officeStatus }}</div></div>
    <p v-if="error" class="office-error" role="alert">{{ error }}</p><a v-if="needsMfa" href="/account-security">Open Account security</a>
    <p v-if="encounter.state==='ending'" class="office-notice" role="status">Ending the session and disconnecting everyone. The next visit stays locked until disconnection completes.</p><p v-else-if="encounter.hasParticipants && encounter.state==='active'" class="office-notice">This encounter stays open until you end it, even if the client leaves.</p>
    <template v-if="room">
      <div class="office-link-bar"><label for="office-guest-link">Your guest link</label><input id="office-guest-link" readonly :value="joinUrl" @focus="$event.target.select()" /><button @click="copy">{{ copied ? 'Copied' : 'Copy link' }}</button></div>
      <OfficeDayList :compact="!!video||!!externalMeeting" :agency-id="effectiveAgencyId" :locked="agendaLocked" :active-key="activeAgendaKey" @open="openAgenda" @loaded="agendaItems=$event" />
      <div class="office-layout">
        <div class="office-main">
          <section v-if="externalMeeting" class="office-full-meeting"><header><strong>{{externalMeeting.title}}</strong><button @click="closeFullMeeting">Return to office</button></header><iframe :src="externalMeeting.path" :title="externalMeeting.title" allow="camera; microphone; display-capture; fullscreen; clipboard-write" referrerpolicy="no-referrer" /></section>
          <div v-else-if="video && encounter.scheduled" class="office-video"><button v-if="encounter.state==='ended'" @click="video=null;activeAgendaKey=''">Return to office</button><CounselingSessionView :key="encounter.scheduled.id" :session-ref="String(encounter.scheduled.id)" embedded auto-join @connected="onConnected" @session-ended="scheduledEnded" /></div>
          <div v-else-if="video" class="office-video"><TherapySessionWorkspace :key="video.sessionId" :video="video" :is-host="true" :started-at="encounter.startedAt || null" :show-brand="false" :branding="room.branding" :product-name="productName" :request="workspaceRequest" @connected="onConnected" @leave-request="tutoring ? requestEndTutoring() : end()" @disconnected="onDisconnect" @meeting-ended="onDisconnect" /></div>
          <div v-else class="office-welcome"><div class="welcome-symbol"><Video :size="34" /></div><p class="eyebrow">{{ room.displayName ? `${room.displayName}’s office` : 'Your virtual office' }}</p><h2>A place to connect.</h2><p>Open your camera and microphone when you’re ready.<br />Guests stay in the waiting room until you let them in.</p><button class="primary" :disabled="busy || encounter.state==='ending'" @click="open"><Video :size="18" />{{ encounter.state==='active' ? 'Reconnect to current session' : 'Open office video' }}</button></div>
          <section v-if="video && !encounter.scheduled && !tutoring && admitted.length" class="tutoring-guide"><h2>Open a student’s learning binder</h2><p>Choose the student you have admitted to load their learning plan, package, and materials. The binder is private to you.</p><button v-if="!binderOpen" type="button" @click="chooseBinder">Choose student</button><form v-else @submit.prevent="openBinder"><label>Student<select v-model="binderClientId" required><option value="" disabled>Select student</option><option v-for="student in binderStudents" :key="student.id" :value="student.id">{{student.displayName}}</option></select></label><label v-if="admitted.length>1">Guest in your office<select v-model="binderVisitId" required><option value="" disabled>Select guest</option><option v-for="guest in admitted" :key="guest.id" :value="guest.id">{{guest.guestDisplayName}}</option></select></label><label class="binder-confirm"><input type="checkbox" v-model="binderIdentityConfirmed" required /> I confirm this is the student admitted to my office.</label><button type="submit" :disabled="busy || !binderClientId || !binderIdentityConfirmed">Open learning binder</button><p v-if="!binderStudents.length">No tutoring students are currently assigned to you with this agency.</p></form></section>
          <section v-if="video && tutoring && activeTutoringStudent" class="tutoring-guide"><header><h2>{{activeTutoringStudent.displayName}}’s tutoring visit</h2><label v-if="tutoring.participants.length>1">Student materials<select v-model="tutoringStudentId"><option v-for="student in tutoring.participants" :key="student.id" :value="student.id">{{student.displayName}}</option></select></label><p>Only you can see the session guide. Use the session tools above to share materials with admitted students.</p></header><TutorSessionGuidePanel :key="`${encounter.generation}:${activeTutoringStudent.id}`" :client-id="activeTutoringStudent.id" :agency-id="effectiveAgencyId" :session-id="tutoring.participants.length===1?tutoring.learningSessionId:null" :initial-subject-id="tutoring.participants.length===1?tutoring.student_subject_id:null" :student-name="activeTutoringStudent.displayName" :grade-label="String(activeTutoringStudent.grade||'')" /></section>
          <div v-if="video && !canAdmit && encounter.state==='active'" class="office-notice" role="status">{{ connected ? 'Confirming your video connection before admission. This updates automatically.' : 'Connecting your camera and microphone…' }}</div>
          <button v-if="!video && !externalMeeting && ['active','ending'].includes(encounter.state)" class="end-button" :disabled="busy" @click="end">{{ encounter.state==='ending' ? 'Retry disconnection' : 'End session for everyone' }}</button>
        </div>
        <aside class="office-lobby" aria-label="Office waiting room"><header class="lobby-heading"><h2>Waiting room</h2><span>{{ waiting.length + scheduledWaiting.length + pendingAppointments.reduce((total,item)=>total+item.waitingCount,0) }}</span></header>
          <p class="lobby-description">Only you can see who’s waiting.</p>
          <div v-if="!waiting.length && !scheduledWaiting.length && !pendingAppointments.length" class="lobby-empty"><Users :size="28" /><strong>You’re all caught up</strong><p>Guests will appear here when they check in.</p></div>
          <div v-if="encounter.scheduled" class="current-appointment"><small>CURRENT SESSION</small><strong>{{encounter.scheduled.title}}</strong></div>
          <article v-for="item in pendingAppointments" :key="item.key" class="guest-card"><div class="guest-identity"><div class="guest-initial"><Users :size="20" /></div><div><strong>{{item.title}}</strong><small>{{item.agencyName}} · {{item.waitingCount}} waiting via personal links</small></div></div><button class="admit-button" :disabled="busy||agendaLocked" @click="openAgenda(item)">Open appointment</button><small v-if="agendaLocked">Finish the current visit first.</small></article>
          <article v-for="guest in scheduledWaiting" :key="`scheduled-${guest.id}`" class="guest-card"><div class="guest-identity"><div class="guest-initial">{{guest.guestDisplayName.slice(0,1)}}</div><div><strong>{{guest.guestDisplayName}}</strong><small>Personal session link</small></div></div><button class="primary admit-button" :disabled="!canAdmit||busy" @click="admitScheduled(guest.id)">Admit to scheduled session</button></article>
          <article v-for="guest in waiting" :key="guest.id" class="guest-card"><div class="guest-identity"><button v-if="guest.guestPhotoUrl" class="photo-button" :aria-label="`Enlarge photo of ${guest.guestDisplayName}`" @click="selectedPhoto=guest"><img :src="guest.guestPhotoUrl" :alt="`Snapshot supplied by ${guest.guestDisplayName}`" /></button><div v-else class="guest-initial">{{ guest.guestDisplayName.slice(0,1) }}</div><div><strong>{{ guest.guestDisplayName }}</strong><small>{{ guest.guestPhotoUrl ? 'Select photo to enlarge' : 'No photo supplied' }}</small></div></div>
            <button class="primary admit-button" :disabled="!canAdmit || busy || (encounter.hasParticipants && !sessionToIdentify && !guest.returning)" @click="prepareAdmission(guest)">{{ tutoring ? 'Admit to this tutoring session' : sessionToIdentify ? `Identify and admit ${guest.guestDisplayName}` : guest.returning ? `Readmit ${guest.guestDisplayName}` : `Start session with ${guest.guestDisplayName}` }}</button><button v-if="!sessionToIdentify && encounter.hasParticipants && admitted.length && plan.multipleOfficeGuests && encounter.state==='active'" :disabled="!canAdmit || busy" @click="sameSessionGuest=guest">Add to this couples / family session</button><button v-if="tutoring && encounter.hasParticipants" class="next-student-button" :disabled="busy || encounter.state!=='active'" @click="requestEndTutoring">End tutoring session before next student</button><button class="message-guest-button" @click="messageGuest=guest">Message {{ guest.guestDisplayName }}<span v-if="guest.unreadMessages"> · {{ guest.unreadMessages }} unread</span></button><button class="dismiss-button" :disabled="busy" @click="dismiss(guest.id)">Dismiss</button>
          </article>
          <section v-if="admitted.length || scheduledAdmitted.length" class="admitted-guests"><h3>In this session <span>{{ admitted.length + scheduledAdmitted.length }}</span></h3><p v-for="guest in [...admitted,...scheduledAdmitted]" :key="`${guest.entryMethod||'office'}-${guest.id}`"><span class="presence-dot"></span>{{ guest.guestDisplayName }}<button v-if="!guest.entryMethod || guest.entryMethod==='office_link'" @click="messageGuest=guest">Message<span v-if="guest.unreadMessages"> · {{ guest.unreadMessages }} unread</span></button></p></section>
          <OfficeWaitingMessages v-if="messageGuest" :key="`${effectiveAgencyId}-${messageGuest.id}`" :request="messageRequest" :recipient="messageGuest.guestDisplayName" role="provider" closable @close="messageGuest=null" />
          <p v-if="!video && waiting.length" class="lobby-hint">Open office video to welcome your guest.</p><p v-else-if="encounter.hasParticipants && !admitted.length && !scheduledAdmitted.length" class="lobby-hint">End the current session before starting another visit.</p>
        </aside>
      </div>
    </template>
    <section v-if="identityGuest" class="same-session-confirm" role="dialog" aria-modal="true" aria-label="Confirm scheduled client"><h2>Identify {{identityGuest.guestDisplayName}}</h2><p v-if="proposedAppointment">Possible appointment: <strong>{{proposedAppointment.title}}</strong>. The time overlaps this visit.</p><p>{{ tutoring ? "Choose the student this person is joining. A parent or other invited participant will see this tutoring session’s shared content." : "Confirm their identity before linking this visit and its content to the scheduled client’s record." }}</p><label>{{ tutoring ? 'Student' : 'Scheduled client' }}<select v-model="confirmedClientId"><option value="">Select a client</option><option v-for="client in sessionToIdentify?.participants || proposedAppointment?.participants || []" :key="client.id" :value="client.id">{{client.displayName}}</option></select></label><label v-if="encounter.hasParticipants"><input v-model="sameScheduledEncounter" type="checkbox" /> This is the same client returning, or an intended participant in this session.</label><button :disabled="busy || !confirmedClientId || (encounter.hasParticipants&&!sameScheduledEncounter)" @click="confirmScheduledGuest">Confirm and admit</button><button v-if="proposedAppointment" :disabled="busy" @click="admitUnscheduled">Continue as an unscheduled visit</button><button @click="identityGuest=null;proposedAppointment=null">Cancel</button></section>
    <section v-if="closeTutoringPrompt" class="same-session-confirm" role="dialog" aria-modal="true" aria-label="End tutoring session"><h2>Close and end tutoring session?</h2><p>{{ admitted.length ? 'Everyone in this tutoring session will be disconnected.' : 'Your guests have left.' }} We’ll put away this student’s binder and shared materials, then prepare your office for the next student.</p><p>Your office link stays the same.</p><button class="primary" :disabled="busy" @click="endTutoringAndContinue">Yes, end and prepare my office</button><button :disabled="busy" @click="closeTutoringPrompt=false">Keep this session open</button></section>
    <section v-if="sameSessionGuest" class="same-session-confirm" role="dialog" aria-modal="true" aria-label="Add to current session"><h2>Add {{ sameSessionGuest.guestDisplayName }} to this session?</h2><p>Only continue if they are an intended participant in this couples or family session. They will see its shared content.</p><button :disabled="busy" @click="admit(sameSessionGuest.id,true)">Add to current session</button><button @click="sameSessionGuest=null">Cancel</button></section>
    <div v-if="plan && !plan.privateOffice"><p>Your plan includes Note Workspace. Upgrade to Premium for a private office, or Premium Plus for multiple office guests.</p></div>
    <dialog ref="photoDialog" :open="!!selectedPhoto" class="photo-dialog" @keydown.esc="selectedPhoto=null"><template v-if="selectedPhoto"><h2>{{ selectedPhoto.guestDisplayName }}</h2><img :src="selectedPhoto.guestPhotoUrl" :alt="selectedPhoto.guestDisplayName" /><button @click="selectedPhoto=null">Close photo</button></template></dialog>
    <details v-if="room" @toggle="loadHistory"><summary>Visit history &amp; audit log</summary><label class="history-grouping">Group history <select v-model="historyGrouping"><option value="visit">By visit</option><option value="ip">By IP address</option></select></label><div class="history-scroll"><table><thead><tr><th>Guest</th><th>Joined through</th><th>Appointment</th><th>IP address</th><th>Admitted</th><th>Admitted duration</th><th>Video duration</th><th>Status</th><th>Session content</th></tr></thead><tbody v-for="group in historyGroups" :key="group.key"><tr v-if="historyGrouping==='ip'" class="history-group"><th colspan="9">{{group.label}} · {{group.visits.length}} {{group.visits.length===1?'visit':'visits'}}</th></tr><tr v-for="visit in group.visits" :key="visit.key||visit.id"><td>{{ visit.displayName }}</td><td>{{ entryLabel(visit.entryMethod) }}</td><td>{{visit.sessionTitle||'Unscheduled office visit'}}<small v-if="visit.recordSyncPending"> · Record sync pending</small></td><td>{{ visit.ipAddress || 'Unavailable' }}</td><td>{{ new Date(visit.admittedAt).toLocaleString() }}</td><td>{{ visit.durationSeconds == null ? 'In progress' : `${Math.floor(visit.durationSeconds/60)}m ${visit.durationSeconds%60}s` }}</td><td>{{ visit.mediaDurationSeconds == null ? 'Not confirmed' : `${visit.mediaDurationSeconds}s` }}<small v-if="visit.clientConnectedSeconds != null"> · Client total: {{visit.clientConnectedSeconds}}s across rejoins</small></td><td>{{ visit.status }}</td><td><button @click="viewArtifacts(visit.generation)">View files</button></td></tr></tbody></table></div></details>
    <section v-if="historyArtifacts" class="history-files"><h2>Saved session content</h2><button @click="historyArtifacts=null">Close files</button><p v-if="!historyArtifacts.length">No shared content in this visit.</p><article v-for="a in historyVisibleArtifacts" :key="a.id"><strong>{{ a.payload.title || a.type }}</strong><small> · {{ a.role }}</small><p v-if="a.payload.text">{{ a.payload.text }}</p><p v-for="(answer,i) in a.payload.answers || []" :key="i">{{ answer }}</p><a v-if="a.payload.document" :href="a.payload.document" :download="`${a.payload.title || 'attachment'}.pdf`" @click.prevent="downloadHistory(a)">Download PDF</a><a v-if="a.payload.url" :href="a.payload.url" target="_blank" rel="noopener noreferrer">Open resource</a><svg v-if="a.type==='drawing'" viewBox="0 0 1000 700" aria-label="Saved drawing"><polyline v-for="stroke in historyArtifacts.filter(item=>item.type==='drawing'&&item.payload.shareId===a.payload.shareId)" :key="stroke.id" :points="stroke.payload.points.map(p=>p.join(',')).join(' ')" :stroke="stroke.payload.color" fill="none" stroke-width="4" /></svg></article></section>
    <p v-if="plan?.grandfathered">Your existing account includes Premium Plus.</p>
  </section>
</template>
<script setup>
import { isAuricWellOffice, officeAccent } from '../../utils/officeBranding';
import { registerClinicalWorkspace } from '../../composables/useClinicalWorkspace';
import OfficeDayList from './OfficeDayList.vue';
import {officeMeetingTarget} from '../../utils/officeAgenda';
import OfficeBrand from './OfficeBrand.vue';
import OfficeWaitingMessages from './OfficeWaitingMessages.vue';
import { Video, Users } from '@lucide/vue';
import '../../styles/clinicalWorkspace.css';
import { computed, defineAsyncComponent, onMounted, onBeforeUnmount, ref, nextTick } from 'vue';
import TherapySessionWorkspace from './TherapySessionWorkspace.vue';
import TutorSessionGuidePanel from '../tutoring/TutorSessionGuidePanel.vue';
import { virtualOfficeGuestUrl } from '../../utils/virtualOfficeLinks.js';
const CounselingSessionView=defineAsyncComponent(()=>import('../../views/counseling/CounselingSessionView.vue'));
const emit=defineEmits(['change-agency']);
const props=defineProps({initialSelection:Object,agencyId:{type:Number,default:0},request:{type:Function,required:true},publicOrigin:{type:String,default:''},productName:{type:String,default:'AuricWell'}});
const call=(path,method='GET',body)=>props.request(path,{method,body});
const room=ref(null),plan=ref(null),waiting=ref([]),admitted=ref([]),video=ref(null),connected=ref(false),error=ref(''),busy=ref(false),copied=ref(false);
const messageGuest=ref(null);
const messageRequest=options=>props.request(`/me/visits/${messageGuest.value.id}/messages`,options);
const effectiveAgencyId=computed(()=>Number(room.value?.agencyId||props.agencyId));
const auricwell=computed(()=>isAuricWellOffice(room.value?.branding));
registerClinicalWorkspace(auricwell);
const joinUrl=computed(()=>virtualOfficeGuestUrl(room.value?.slug, room.value?.branding?.officeOrigin || props.publicOrigin || (auricwell.value ? 'https://auricwell.com' : window.location.origin)));
const agendaItems=ref([]),proposedAppointment=ref(null);
const tutoringStudentId=ref(null);
const closeTutoringPrompt=ref(false),resumeAfterTutoringEnd=ref(false);let promptedGeneration=null;
function requestEndTutoring(){promptedGeneration=encounter.value.generation;closeTutoringPrompt.value=true;}
const binderOpen=ref(false),binderStudents=ref([]),binderClientId=ref(''),binderVisitId=ref(''),binderIdentityConfirmed=ref(false);
const chooseBinder=()=>action(async()=>{binderStudents.value=(await call('/me/tutoring-students')).students||[];binderVisitId.value=admitted.value.length===1?admitted.value[0].id:'';binderClientId.value='';binderIdentityConfirmed.value=false;binderOpen.value=true;});
const openBinder=()=>action(async()=>{await call('/me/tutoring-binder','POST',{clientId:Number(binderClientId.value),visitId:Number(binderVisitId.value),confirmIdentity:binderIdentityConfirmed.value});binderOpen.value=false;await refresh();});
const tutoring=computed(()=>encounter.value.tutoring);
const activeTutoringStudent=computed(()=>tutoring.value?.participants?.find(c=>c.id===Number(tutoringStudentId.value))||tutoring.value?.participants?.[0]||null);
const sessionToIdentify=computed(()=>encounter.value.scheduled||tutoring.value);
const scheduledWaiting=ref([]),scheduledAdmitted=ref([]),externalMeeting=ref(null),activeAgendaKey=ref(''),identityGuest=ref(null),confirmedClientId=ref(''),sameScheduledEncounter=ref(false);
const pendingAppointments=computed(()=>agendaItems.value.filter(item=>item.type==='clinical'&&item.waitingCount>0&&Number(item.sessionId)!==Number(encounter.value.scheduled?.id)));
const agendaLocked=computed(()=>!!externalMeeting.value||encounter.value.state==='ending'||(encounter.value.state==='active'&&(encounter.value.hasParticipants||!!encounter.value.scheduled||!!encounter.value.tutoring)));
const encounter=ref({state:'idle',hasParticipants:false}),sameSessionGuest=ref(null),needsMfa=ref(false);
const canAdmit=computed(()=>connected.value && encounter.value.state==='active' && encounter.value.providerReady===true);
const officeStatus=computed(()=>encounter.value.state==='ending'?'Finishing session':encounter.value.state==='ended'&&video.value?'Session complete':canAdmit.value?((admitted.value.length+scheduledAdmitted.value.length)?'In session':'Ready to welcome guests'):video.value?'Connecting':'Office ready');
const historyGeneration=ref(0),historyGrouping=ref('visit');
const historyGroups=computed(()=>{
 if(historyGrouping.value!=='ip')return [{key:'all',visits:history.value}];
 const groups=new Map();
 for(const visit of history.value){const key=visit.ipAddress||'unavailable';if(!groups.has(key))groups.set(key,{key,label:visit.ipAddress?`IP ${visit.ipAddress}`:'IP unavailable',visits:[]});groups.get(key).visits.push(visit);}
 return [...groups.values()];
});
const selectedPhoto=ref(null),history=ref([]),historyArtifacts=ref(null);
const historyVisibleArtifacts=computed(()=>(historyArtifacts.value||[]).filter(a=>a.type!=='drawing'||!historyArtifacts.value.some(other=>other.type==='drawing'&&other.payload.shareId===a.payload.shareId&&other.id>a.id)));
const viewArtifacts=generation=>action(async()=>{historyGeneration.value=generation;historyArtifacts.value=[];let afterId=0,more=true;while(more){const data=await call(`/me/history/${generation}/artifacts?afterId=${afterId}`);historyArtifacts.value.push(...data.artifacts);afterId=data.nextCursor;more=data.hasMore;}});
const downloadHistory=a=>action(async()=>{await call(`/me/history/${historyGeneration.value}/artifacts/download`,'POST',{artifactId:a.id});const link=document.createElement('a');link.href=a.payload.document;link.download=`${a.payload.title || 'attachment'}.pdf`;link.click();});
const workspaceRequest=(_path,options)=>props.request(`/me/workspace${_path}`,options);
async function loadHistory(e){if(e.target.open)await action(async()=>{history.value=(await call('/me/history')).visits;});}
let timer,stopped=false,lobbyRequestVersion=0;
async function action(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){needsMfa.value=e.response?.data?.error?.code==='MFA_REQUIRED';error.value=e.response?.data?.error?.message||e.message;}finally{busy.value=false;}}
async function refresh(){const version=++lobbyRequestVersion;try{const data=await call('/me/lobby');if(stopped||version!==lobbyRequestVersion)return;waiting.value=data.waiting;admitted.value=data.admitted;scheduledWaiting.value=data.scheduledWaiting||[];scheduledAdmitted.value=data.scheduledAdmitted||[];encounter.value=data.encounter||{state:'idle',hasParticipants:false};if(encounter.value.state!=='active'){if(!encounter.value.scheduled)video.value=null;connected.value=false;if(!externalMeeting.value)activeAgendaKey.value='';}if(connected.value)await call('/me/heartbeat','POST');
 if(admitted.value.length)promptedGeneration=null;
 if(tutoring.value&&video.value&&encounter.value.state==='active'&&encounter.value.hasParticipants&&!admitted.value.length&&!resumeAfterTutoringEnd.value&&promptedGeneration!==encounter.value.generation){promptedGeneration=encounter.value.generation;closeTutoringPrompt.value=true;}
 if(resumeAfterTutoringEnd.value&&encounter.value.state==='ended'&&!busy.value)await action(async()=>{resumeAfterTutoringEnd.value=false;await call('/me/end','POST');await reopenEmptyOffice();});}catch(e){if(stopped||version!==lobbyRequestVersion)return;needsMfa.value=e.response?.data?.error?.code==='MFA_REQUIRED';error.value=e.response?.data?.error?.message||e.message;if([401,403,404].includes(Number(e.response?.status||e.status))){video.value=null;connected.value=false;}}}
const open=()=>action(async()=>{if(externalMeeting.value)throw new Error('Return from the current meeting first.');video.value=await call('/me/video-token','POST');await refresh();});
async function onConnected(){connected.value=true;await refresh();}
function putAwayTutoringMaterials(){
 lobbyRequestVersion++;messageGuest.value=null;
 closeTutoringPrompt.value=false;video.value=null;connected.value=false;tutoringStudentId.value=null;binderOpen.value=false;binderStudents.value=[];binderClientId.value='';binderVisitId.value='';binderIdentityConfirmed.value=false;historyArtifacts.value=null;identityGuest.value=null;sameSessionGuest.value=null;proposedAppointment.value=null;activeAgendaKey.value='';
}
async function reopenEmptyOffice(){await nextTick();video.value=await call('/me/video-token','POST');await refresh();}
const endTutoringAndContinue=()=>action(async()=>{
 const result=await call('/me/end','POST');putAwayTutoringMaterials();await nextTick();
 if(result.state==='ended'){resumeAfterTutoringEnd.value=false;await reopenEmptyOffice();}
 else{resumeAfterTutoringEnd.value=true;await refresh();}
});
const end=()=>action(async()=>{await call('/me/end','POST');resumeAfterTutoringEnd.value=false;putAwayTutoringMaterials();await refresh();});
function onDisconnect(){connected.value=false;video.value=null;void refresh();}
const admit=(id,sameEncounter=false)=>action(async()=>{try{await call(`/lobby/${id}/admit`,'POST',{sameEncounter});sameSessionGuest.value=null;}finally{await refresh();}});
const dismiss=id=>action(async()=>{await call(`/lobby/${id}/dismiss`,'POST');await refresh();});
const entryLabel=method=>({office_link:'Permanent office link',invitation:'Personal invitation',authenticated:'Signed-in client',session_link:'Session link'}[method]||'Permanent office link');
function prepareAdmission(guest){
 const candidates=agendaItems.value.filter(item=>item.type==='clinical'&&item.canOpen&&Number(item.agencyId)===effectiveAgencyId.value&&item.participants?.length&&new Date(item.startAt).getTime()-1800000<=Date.now()&&new Date(item.endAt).getTime()+1800000>=Date.now());
 proposedAppointment.value=!encounter.value.hasParticipants&&!encounter.value.scheduled&&candidates.length===1?candidates[0]:null;
 if(sessionToIdentify.value||proposedAppointment.value){identityGuest.value=guest;confirmedClientId.value='';sameScheduledEncounter.value=false;}else void admit(guest.id);
}
async function admitUnscheduled(){const id=identityGuest.value.id;identityGuest.value=null;proposedAppointment.value=null;await admit(id);}
const confirmScheduledGuest=()=>action(async()=>{if(proposedAppointment.value){const item=proposedAppointment.value;video.value=await call('/me/video-token','POST',{appointmentId:item.appointmentId});await refresh();activeAgendaKey.value=item.key;proposedAppointment.value=null;}await call(`/lobby/${identityGuest.value.id}/admit`,'POST',{clientId:Number(confirmedClientId.value),confirmIdentity:true,sameEncounter:sameScheduledEncounter.value});identityGuest.value=null;await refresh();});
const admitScheduled=id=>action(async()=>{await call(`/me/scheduled-visits/${id}/admit`,'POST');await refresh();});
async function scheduledEnded(){connected.value=false;await refresh();}
function closeFullMeeting(){externalMeeting.value=null;activeAgendaKey.value='';void refresh();}
async function openAgenda(item){
 if(item.agencyId&&Number(item.agencyId)!==effectiveAgencyId.value&&['clinical','tutoring'].includes(item.type)){
  if(['active','ending'].includes(encounter.value.state)||externalMeeting.value){error.value='End the current visit before switching agencies.';return;}
  emit('change-agency',item);return;
 }
 await action(async()=>{
  if(agendaLocked.value){if(item.key===activeAgendaKey.value)return;throw new Error('End the active visit before opening another meeting.');}
  if(item.type==='tutoring'){
   video.value=await call('/me/video-token','POST',{learningSessionId:item.learningSessionId,tutoringAppointmentId:item.tutoringAppointmentId});await refresh();
  }else if(item.type==='clinical'){
   video.value=await call('/me/video-token','POST',{appointmentId:item.appointmentId||undefined,sessionId:item.appointmentId?undefined:item.sessionId});await refresh();
  }else{
   if(encounter.value.state==='active')throw new Error('End your office video before opening this meeting.');
   const target=officeMeetingTarget(item.url);if(!target)throw new Error('This meeting link is unavailable.');
   if(!target.embedded){window.open(target.path,'_blank','noopener,noreferrer');return;}
   externalMeeting.value={...item,path:target.path};
  }
  activeAgendaKey.value=item.key;
 });
}
const copy=()=>action(async()=>{await navigator.clipboard.writeText(joinUrl.value);copied.value=true;});
onMounted(async()=>{await action(async()=>{plan.value=(await call('/me/plan')).plan;if(plan.value.privateOffice){room.value=(await call('/me')).room;await refresh();}});if(!stopped&&room.value){timer=setInterval(refresh,5000);if(props.initialSelection)await openAgenda(props.initialSelection);}});
onBeforeUnmount(()=>{stopped=true;clearInterval(timer);});
</script>
